CREATE TABLE principals(email TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('owner','editor','reviewer')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE editorial_items(id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,summary TEXT NOT NULL,source_refs TEXT NOT NULL DEFAULT '[]',evidence_class TEXT NOT NULL DEFAULT 'authoredInterpretation',state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','review','approved','withdrawn')),revision INTEGER NOT NULL DEFAULT 1,source_revision TEXT NOT NULL DEFAULT '',updated_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_at TEXT,approved_by TEXT);
CREATE TABLE editorial_history(item_id TEXT NOT NULL,revision INTEGER NOT NULL,data TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(item_id,revision));
CREATE TABLE audit_events(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agent_proposals(id TEXT PRIMARY KEY,proposer TEXT NOT NULL,title TEXT NOT NULL,plan TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'proposed',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_by TEXT,reviewed_at TEXT);
CREATE TABLE deployment_records(id TEXT PRIMARY KEY,target TEXT NOT NULL,artifact_sha TEXT,state TEXT NOT NULL,evidence_url TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE private_inquiries(id TEXT PRIMARY KEY,received_at TEXT NOT NULL,topic TEXT NOT NULL,reply_email TEXT,message TEXT NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',retention_until TEXT);
CREATE INDEX idx_editorial_state ON editorial_items(state,kind,updated_at);
CREATE INDEX idx_audit_created ON audit_events(created_at DESC);
-- Owner principal is configured privately in the live D1 database; no private identity is seeded into the public repository.